css_snippet:
body {
    font-family: "Inter", sans-serif; /* Requires a variable font with an 'opsz' (optical size) axis */
    font-optical-sizing: auto; /* Enables automatic optical sizing based on font-size */
}

h1 {
    font-size: 3.5rem; /* Large text will be optically adjusted for large sizes */
    /* font-optical-sizing: auto; is inherited here */
}

p {
    font-size: 1rem; /* Small text will be optically adjusted for small sizes */
    /* font-optical-sizing: auto; is inherited here */
}
